func NodeUtil_canBeSideEffected_Node_Set_Scope(n Node, knownConstants *JTSet[string], scope *Scope) bool {
	switch n.ns_().token {
	case tokOrd1_YIELD, tokOrd1_CALL, tokOrd1_OPTCHAIN_CALL, tokOrd1_NEW, tokOrd1_TAGGED_TEMPLATELIT, tokOrd1_AWAIT, tokOrd1_DYNAMIC_IMPORT:
		return true
	case tokOrd1_NAME:
		return (!NodeUtil_isConstantVar(n, scope) && !knownConstants.contains(n.getString()))
	case tokOrd1_GETPROP:
		return !n.getFirstChild().matchesName("Symbol")
	case tokOrd1_GETELEM, tokOrd1_OPTCHAIN_GETPROP, tokOrd1_OPTCHAIN_GETELEM:
		return true
	case tokOrd1_FUNCTION:
		if NodeUtil_isFunctionDeclaration(n) {
			Preconditions_checkState_boolean_Object_H(false, n)
		}
		return false
	default:
	}
	{
		var c Node = n.getFirstChild()
		for ; c != 0; c = c.getNext() {
			if NodeUtil_canBeSideEffected_Node_Set_Scope(c, knownConstants, scope) {
				return true
			}
		}
	}
	return false
}

func NodeUtil_precedence(type_ Token_rhino) int32 {
	return func() int32 {
		switch type_ {
		case Token_rhino_COMMA:
			return 0
		case Token_rhino_ASSIGN_BITOR, Token_rhino_ASSIGN_BITXOR, Token_rhino_ASSIGN_BITAND, Token_rhino_ASSIGN_LSH, Token_rhino_ASSIGN_RSH, Token_rhino_ASSIGN_URSH, Token_rhino_ASSIGN_ADD, Token_rhino_ASSIGN_SUB, Token_rhino_ASSIGN_MUL, Token_rhino_ASSIGN_EXPONENT, Token_rhino_ASSIGN_DIV, Token_rhino_ASSIGN_MOD, Token_rhino_ASSIGN_OR, Token_rhino_ASSIGN_AND, Token_rhino_ASSIGN_COALESCE, Token_rhino_ASSIGN:
			return 1
		case Token_rhino_YIELD:
			return 2
		case Token_rhino_HOOK:
			return 3
		case Token_rhino_OR:
			return 4
		case Token_rhino_AND:
			return 5
		case Token_rhino_COALESCE:
			return 6
		case Token_rhino_BITOR:
			return 7
		case Token_rhino_BITXOR:
			return 8
		case Token_rhino_BITAND:
			return 9
		case Token_rhino_EQ, Token_rhino_NE, Token_rhino_SHEQ, Token_rhino_SHNE:
			return 10
		case Token_rhino_LT, Token_rhino_GT, Token_rhino_LE, Token_rhino_GE, Token_rhino_INSTANCEOF, Token_rhino_IN:
			return 11
		case Token_rhino_LSH, Token_rhino_RSH, Token_rhino_URSH:
			return 12
		case Token_rhino_SUB, Token_rhino_ADD:
			return 13
		case Token_rhino_MUL, Token_rhino_MOD, Token_rhino_DIV:
			return 14
		case Token_rhino_EXPONENT:
			return 15
		case Token_rhino_AWAIT, Token_rhino_NEW, Token_rhino_DELPROP, Token_rhino_TYPEOF, Token_rhino_VOID, Token_rhino_NOT, Token_rhino_BITNOT, Token_rhino_POS, Token_rhino_NEG:
			return 16
		case Token_rhino_INC, Token_rhino_DEC:
			return 17
		case Token_rhino_CALL, Token_rhino_GETELEM, Token_rhino_GETPROP, Token_rhino_OPTCHAIN_CALL, Token_rhino_OPTCHAIN_GETELEM, Token_rhino_OPTCHAIN_GETPROP, Token_rhino_NEW_TARGET, Token_rhino_IMPORT_META, Token_rhino_ARRAYLIT, Token_rhino_ARRAY_PATTERN, Token_rhino_DEFAULT_VALUE, Token_rhino_DESTRUCTURING_LHS, Token_rhino_EMPTY, Token_rhino_FALSE, Token_rhino_FUNCTION, Token_rhino_CLASS, Token_rhino_INTERFACE, Token_rhino_NAME, Token_rhino_NULL, Token_rhino_NUMBER, Token_rhino_BIGINT, Token_rhino_OBJECTLIT, Token_rhino_OBJECT_PATTERN, Token_rhino_REGEXP, Token_rhino_ITER_REST, Token_rhino_OBJECT_REST, Token_rhino_ITER_SPREAD, Token_rhino_OBJECT_SPREAD, Token_rhino_STRINGLIT, Token_rhino_STRING_KEY, Token_rhino_MEMBER_VARIABLE_DEF, Token_rhino_INDEX_SIGNATURE, Token_rhino_CALL_SIGNATURE, Token_rhino_THIS, Token_rhino_SUPER, Token_rhino_TRUE, Token_rhino_TAGGED_TEMPLATELIT, Token_rhino_TEMPLATELIT, Token_rhino_DYNAMIC_IMPORT, Token_rhino_UNION_TYPE:
			return 18
		case Token_rhino_FUNCTION_TYPE:
			return 19
		case Token_rhino_ARRAY_TYPE, Token_rhino_PARAMETERIZED_TYPE:
			return 20
		case Token_rhino_STRING_TYPE, Token_rhino_NUMBER_TYPE, Token_rhino_BOOLEAN_TYPE, Token_rhino_ANY_TYPE, Token_rhino_RECORD_TYPE, Token_rhino_NULLABLE_TYPE, Token_rhino_NAMED_TYPE, Token_rhino_UNDEFINED_TYPE, Token_rhino_VOID_TYPE, Token_rhino_GENERIC_TYPE:
			return 21
		case Token_rhino_CAST:
			return 22
		default:
			if type_ == Token_rhino_TEMPLATELIT_STRING {
				panic(new_IllegalArgumentException_0().self())
			}
			panic(new_IllegalStateException_String(("Unknown precedence for " + jtostr_(type_))).self())
		}
		panic("unreachable")
	}()
}

